function pisahkanKebutuhan(daftar) {
  const hasil = { fungsional: [], nonFungsional: [] };
  for (const k of daftar) {
    if (k.jenis === "fungsional") hasil.fungsional.push(k.id);
    else if (k.jenis === "non-fungsional") hasil.nonFungsional.push(k.id);
  }
  return hasil;
}

