function cekCanary(tahapPersen, errorPerTahap, batas) {
  let persenAman = 0;
  for (let i = 0; i < tahapPersen.length; i++) {
    if (errorPerTahap[i] > batas) return { status: "rollback", persenAman };
    persenAman = tahapPersen[i];
  }
  return { status: "rilis penuh", persenAman };
}

