function itemValid(item) {
  return typeof item.id === "string" && item.id !== "" &&
    [1, 2, 3].includes(item.prioritas) &&
    Number.isInteger(item.poin) && item.poin > 0 &&
    Array.isArray(item.testCase) && item.testCase.length > 0;
}

function rencanakanRilis(backlog, kapasitas) {
  const sprint = [];
  const tertunda = [];
  const siap = [];
  for (const item of backlog) {
    if (!itemValid(item) || item.poin > kapasitas) tertunda.push(typeof item.id === "string" && item.id !== "" ? item.id : null);
    else siap.push(item);
  }
  siap.sort((a, b) => a.prioritas - b.prioritas);
  let isi = [];
  let total = 0;
  for (const item of siap) {
    if (total + item.poin > kapasitas) {
      sprint.push(isi);
      isi = [];
      total = 0;
    }
    isi.push(item.id);
    total += item.poin;
  }
  if (isi.length) sprint.push(isi);
  return { sprint, tertunda };
}
